using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using StudentAccommodationSystem.Data; using StudentAccommodationSystem.Models;
namespace StudentAccommodationSystem.Controllers;
[Authorize] public class NotificationController(ApplicationDbContext db,UserManager<ApplicationUser> users):Controller { public async Task<IActionResult> Index(){var u=await users.GetUserAsync(User);return View(await db.Notifications.Where(x=>x.UserId==u!.Id).OrderByDescending(x=>x.CreatedAt).ToListAsync());} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> MarkRead(int id){var u=await users.GetUserAsync(User);var n=await db.Notifications.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==u!.Id);if(n!=null){n.IsRead=true;await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));} }
